namespace sv_87226e7b88014a22af71c0fb977d6123.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// All interactive components on the same circuit share one instance.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd"; // Bootstrap primary blue

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised whenever Theme or AccentColor changes.
    /// Subscribers should call StateHasChanged().
    /// </summary>
    public event Action? OnChanged;

    private void NotifyChanged() => OnChanged?.Invoke();
}

@*
    Interactive island placed in the static MainLayout.
    Because it carries @rendermode InteractiveServer, it joins the
    circuit and shares the same scoped ThemeService as page components.
*@
@rendermode InteractiveServer
@inject sv_87226e7b88014a22af71c0fb977d6123.Services.ThemeService ThemeSvc
@implements IDisposable

<span class="theme-indicator d-inline-flex align-items-center gap-2">
    <span class="badge"
          style="background-color: @ThemeSvc.AccentColor; color: white;">
        @ThemeSvc.Theme.ToString()
    </span>

    <button class="btn btn-sm btn-outline-secondary"
            @onclick="CycleTheme"
            title="Toggle theme">
        @ThemeIcon
    </button>
</span>

@code {
    private string ThemeIcon => ThemeSvc.Theme switch
    {
        sv_87226e7b88014a22af71c0fb977d6123.Services.ThemeMode.Light  => "☀️",
        sv_87226e7b88014a22af71c0fb977d6123.Services.ThemeMode.Dark   => "🌙",
        _                                                              => "💻"
    };

    protected override void OnInitialized()
    {
        ThemeSvc.OnChanged += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void CycleTheme()
    {
        ThemeSvc.Theme = ThemeSvc.Theme switch
        {
            sv_87226e7b88014a22af71c0fb977d6123.Services.ThemeMode.Light  => sv_87226e7b88014a22af71c0fb977d6123.Services.ThemeMode.Dark,
            sv_87226e7b88014a22af71c0fb977d6123.Services.ThemeMode.Dark   => sv_87226e7b88014a22af71c0fb977d6123.Services.ThemeMode.System,
            _                                                              => sv_87226e7b88014a22af71c0fb977d6123.Services.ThemeMode.Light
        };
    }

    public void Dispose()
    {
        ThemeSvc.OnChanged -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject sv_87226e7b88014a22af71c0fb977d6123.Services.ThemeService ThemeSvc
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var mode in Enum.GetValues<sv_87226e7b88014a22af71c0fb977d6123.Services.ThemeMode>())
            {
                var isActive = ThemeSvc.Theme == mode;
                <button type="button"
                        class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => ThemeSvc.Theme = mode">
                    @mode.ToString()
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <div class="d-flex align-items-center gap-3 mb-3">
            <input type="color"
                   class="form-control form-control-color"
                   value="@ThemeSvc.AccentColor"
                   @onchange="OnColorChanged" />
            <span class="font-monospace">@ThemeSvc.AccentColor</span>
        </div>

        <h5 class="card-title">Preview</h5>
        <div class="p-3 rounded"
             style="background-color: @ThemeSvc.AccentColor; color: white;">
            Current theme: <strong>@ThemeSvc.Theme</strong>
            — Accent: <strong>@ThemeSvc.AccentColor</strong>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChanged += HandleThemeChanged;
    }

    private void OnColorChanged(ChangeEventArgs e)
    {
        ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChanged -= HandleThemeChanged;
    }
}

