@page "/settings"
@rendermode InteractiveServer
@inject sv_87226e7b88014a22af71c0fb977d6123.Services.ThemeService ThemeSvc
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var mode in Enum.GetValues<sv_87226e7b88014a22af71c0fb977d6123.Services.ThemeMode>())
            {
                var isActive = ThemeSvc.Theme == mode;
                <button type="button"
                        class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => ThemeSvc.Theme = mode">
                    @mode.ToString()
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <div class="d-flex align-items-center gap-3 mb-3">
            <input type="color"
                   class="form-control form-control-color"
                   value="@ThemeSvc.AccentColor"
                   @onchange="OnColorChanged" />
            <span class="font-monospace">@ThemeSvc.AccentColor</span>
        </div>

        <h5 class="card-title">Preview</h5>
        <div class="p-3 rounded"
             style="background-color: @ThemeSvc.AccentColor; color: white;">
            Current theme: <strong>@ThemeSvc.Theme</strong>
            — Accent: <strong>@ThemeSvc.AccentColor</strong>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChanged += HandleThemeChanged;
    }

    private void OnColorChanged(ChangeEventArgs e)
    {
        ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChanged -= HandleThemeChanged;
    }
}

